sql.where:
AND so.source_type = 'CUSTOM'

    AND so.outbound_no LIKE CONCAT('%', #{qo.outboundNo}, '%')


    AND so.custom_type = #{qo.customType}


    AND EXISTS (
        SELECT 1 FROM wms_sales_outbound_order_item soi
        WHERE soi.outbound_order_id = so.id
        AND soi.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%')
    )


    AND so.warehouse_id = #{qo.warehouseId}


    AND so.order_status = #{qo.orderStatus}


    AND so.outbound_date >= #{qo.outboundDateStart}


    AND so.outbound_date <= #{qo.outboundDateEnd}
